import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { AirportListSchema, createAirportIndex, type AirportIndex } from './airportData';

/** The airport file is generated by `pnpm data:airports` and is not part of the repository. */
export const airportsFile = (dataDir: string) => join(dataDir, 'airports', 'airports.json');

export class AirportDataMissingError extends Error {
  constructor(readonly file: string) {
    super(`No airport data at ${file}; run "pnpm data:airports" once`);
    this.name = 'AirportDataMissingError';
  }
}

/**
 * Loads the airport index on first use and keeps it. While the file is missing, every call
 * tries again, so running `pnpm data:airports` works without restarting the server.
 */
export function createAirportStore(dataDir: string) {
  const file = airportsFile(dataDir);
  let loading: Promise<AirportIndex> | undefined;

  async function load(): Promise<AirportIndex> {
    let text: string;
    try {
      text = await readFile(file, 'utf8');
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
        throw new AirportDataMissingError(file);
      }
      throw error;
    }
    return createAirportIndex(AirportListSchema.parse(JSON.parse(text)));
  }

  return {
    file,
    index(): Promise<AirportIndex> {
      loading ??= load().catch((error: unknown) => {
        loading = undefined;
        throw error;
      });
      return loading;
    },
  };
}

export type AirportStore = ReturnType<typeof createAirportStore>;
